import{_ as r,o as a,c as n,ag as s}from"./chunks/framework.i8sMDeRW.js";const c=JSON.parse('{"title":"AI 产品画布","description":"","frontmatter":{},"headers":[],"relativePath":"guide/01-framework/ai-product-canvas.md","filePath":"guide/01-framework/ai-product-canvas.md","lastUpdated":1778766569000}'),d={name:"guide/01-framework/ai-product-canvas.md"};function o(l,t,e,i,g,h){return a(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="ai-产品画布" tabindex="-1">AI 产品画布 <a class="header-anchor" href="#ai-产品画布" aria-label="Permalink to &quot;AI 产品画布&quot;">​</a></h1><blockquote><p><strong>AI 产品画布（AI Product Canvas）</strong> 是一个系统化的分析框架，帮助产品经理从问题定义到落地交付，全链路规划 AI 产品。它覆盖了传统产品画布无法触及的 AI 特有维度：模型选型、数据策略、评估指标与伦理风险。</p></blockquote><hr><h2 id="一、ai-产品画布全景视图" tabindex="-1">一、AI 产品画布全景视图 <a class="header-anchor" href="#一、ai-产品画布全景视图" aria-label="Permalink to &quot;一、AI 产品画布全景视图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  1. 问题定义    │   2. 用户价值    │   3. 市场定位  │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  4. 模型选型    │   5. 数据策略    │   6. 评估指标  │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  7. 成本模型    │   8. 伦理与风险  │   9. 落地路径  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="二、九大模块详解" tabindex="-1">二、九大模块详解 <a class="header-anchor" href="#二、九大模块详解" aria-label="Permalink to &quot;二、九大模块详解&quot;">​</a></h2><h3 id="模块-1-问题定义" tabindex="-1">模块 1：问题定义 <a class="header-anchor" href="#模块-1-问题定义" aria-label="Permalink to &quot;模块 1：问题定义&quot;">​</a></h3><p><strong>核心问题：我们到底要解决什么？AI 是必要方案吗？</strong></p><table tabindex="0"><thead><tr><th>子项</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>用户痛点</strong></td><td>描述目标用户的真实场景与困难</td><td>客服人工回复慢，用户等待时间长</td></tr><tr><td><strong>现状方案</strong></td><td>当前如何解决？缺点是什么？</td><td>人工客服 + FAQ 页面，但用户找不到答案</td></tr><tr><td><strong>AI 必要性</strong></td><td>为什么必须用 AI？传统方法是否可行？</td><td>问题类型多样性高，规则引擎无法覆盖</td></tr><tr><td><strong>成功标准</strong></td><td>可量化的业务目标</td><td>用户自助解决率 ≥ 80%，平均响应时间 &lt; 30s</td></tr></tbody></table><p><strong>设计原则：</strong> 不要为了 AI 而 AI。先问：这个问题是否可以用 10 行规则代码解决？如果是，不要用 AI。</p><hr><h3 id="模块-2-用户价值" tabindex="-1">模块 2：用户价值 <a class="header-anchor" href="#模块-2-用户价值" aria-label="Permalink to &quot;模块 2：用户价值&quot;">​</a></h3><p><strong>核心问题：AI 如何改善用户体验？价值主张是什么？</strong></p><ul><li><strong>核心价值主张</strong>：一句话说清 AI 带来什么（如&quot;让用户像聊天一样查询任意数据&quot;）</li><li><strong>体验提升点</strong>：速度、准确性、个性化、可访问性、新能力</li><li><strong>竞品对比</strong>：与没有 AI 的竞品相比，差异化的优势在哪</li><li><strong>用户采纳路径</strong>：用户怎么发现并使用 AI 功能（新用户引导、渐进式展示）</li></ul><hr><h3 id="模块-3-市场定位" tabindex="-1">模块 3：市场定位 <a class="header-anchor" href="#模块-3-市场定位" aria-label="Permalink to &quot;模块 3：市场定位&quot;">​</a></h3><p><strong>核心问题：这个 AI 产品在市场上的位置是什么？</strong></p><ul><li><strong>目标用户群</strong>：B2B/B2C？专业用户/大众用户？初期 vs 成熟期</li><li><strong>场景定义</strong>：单点功能 vs 平台能力 vs 独立产品</li><li><strong>壁垒分析</strong>：数据壁垒、模型壁垒、网络效应、品牌壁垒</li><li><strong>定价策略</strong>：按调用量、按订阅、按结果付费、免费增值</li></ul><hr><h3 id="模块-4-模型选型" tabindex="-1">模块 4：模型选型 <a class="header-anchor" href="#模块-4-模型选型" aria-label="Permalink to &quot;模块 4：模型选型&quot;">​</a></h3><p><strong>核心问题：用什么模型来实现功能？选型的权衡是什么？</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>选项</th><th>权衡</th></tr></thead><tbody><tr><td><strong>模型大小</strong></td><td>7B / 13B / 70B / API 大模型</td><td>小模型快但能力弱，大模型强但成本高</td></tr><tr><td><strong>封闭 vs 开源</strong></td><td>GPT-4 / Claude / DeepSeek / LLaMA</td><td>封闭模型效果好但受供应商限制，开源可自托管</td></tr><tr><td><strong>通用 vs 专用</strong></td><td>通用 LLM vs 微调垂直模型</td><td>通用灵活但精度不足，专用精度高但维护成本大</td></tr><tr><td><strong>部署方式</strong></td><td>云端 API / 私有化部署 / 端侧部署</td><td>API 方便但数据安全风险，私有化成本高</td></tr><tr><td><strong>多模态需求</strong></td><td>文本 / 图像 / 音频 / 视频</td><td>模态越多，架构越复杂</td></tr></tbody></table><p><strong>选型决策树：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>是否需要实时响应？ ──是──&gt; 小模型 / 端侧部署</span></span>
<span class="line"><span>否</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>数据是否敏感？ ──是──&gt; 开源模型 + 私有化部署</span></span>
<span class="line"><span>否</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>是否需要超高准确性？ ──是──&gt; 大型 API 模型 + RAG</span></span>
<span class="line"><span>否</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>通用场景 → API 模型可满足</span></span></code></pre></div><p><strong>设计原则：</strong></p><ul><li><strong>先用 API 验证，再考虑自建</strong>：MVP 阶段优先使用成熟的 API 模型（如 DeepSeek、GPT-4），验证 PMF 后再考虑微调或自建</li><li><strong>模型不是越强越好</strong>：强模型带来更高的成本、延迟和幻觉风险，在能力达标的前提下选最轻量的</li><li><strong>预留模型切换能力</strong>：在架构层抽象模型接口，避免锁定</li></ul><hr><h3 id="模块-5-数据策略" tabindex="-1">模块 5：数据策略 <a class="header-anchor" href="#模块-5-数据策略" aria-label="Permalink to &quot;模块 5：数据策略&quot;">​</a></h3><p><strong>核心问题：数据从哪里来？如何管理数据生命周期？</strong></p><table tabindex="0"><thead><tr><th>子项</th><th>说明</th></tr></thead><tbody><tr><td><strong>数据来源</strong></td><td>用户输入、内部知识库、第三方 API、爬取数据、合成数据</td></tr><tr><td><strong>数据质量</strong></td><td>完整性、准确性、一致性、时效性、去重</td></tr><tr><td><strong>数据标注</strong></td><td>是否需要人工标注？标注标准是什么？如何控制质量？</td></tr><tr><td><strong>数据隐私</strong></td><td>PII 脱敏、数据加密、合规要求（GDPR、《个人信息保护法》）</td></tr><tr><td><strong>数据更新</strong></td><td>更新频率、数据版本管理、过期数据清理</td></tr><tr><td><strong>数据规模</strong></td><td>需要多少数据？数据的量级需求与成本</td></tr></tbody></table><p><strong>关键原则：</strong></p><ul><li><strong>Garbage In, Garbage Out</strong> —— 数据质量比模型选择更重要</li><li><strong>数据飞轮</strong>：用户使用产生数据 → 数据改进模型 → 模型提升体验 → 吸引更多用户</li><li><strong>至少预留 30% 的数据作为评估集</strong>，不与训练/微调数据重叠</li></ul><hr><h3 id="模块-6-评估指标" tabindex="-1">模块 6：评估指标 <a class="header-anchor" href="#模块-6-评估指标" aria-label="Permalink to &quot;模块 6：评估指标&quot;">​</a></h3><p><strong>核心问题：如何衡量 AI 产品好不好？</strong></p><h4 id="_6-1-模型质量指标" tabindex="-1">6.1 模型质量指标 <a class="header-anchor" href="#_6-1-模型质量指标" aria-label="Permalink to &quot;6.1 模型质量指标&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指标</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>准确率 (Accuracy)</strong></td><td>正确预测 / 总预测</td><td>分类任务</td></tr><tr><td><strong>精确率 &amp; 召回率</strong></td><td>精确率：预测为正中的真正例比例；召回率：实际为正中被识别出的比例</td><td>异常检测、信息检索</td></tr><tr><td><strong>F1 Score</strong></td><td>精确率与召回率的调和平均</td><td>不平衡数据集</td></tr><tr><td><strong>BLEU / ROUGE</strong></td><td>生成文本与参考文本的相似度</td><td>翻译、摘要</td></tr><tr><td><strong>Perplexity</strong></td><td>模型预测的困惑度</td><td>语言模型评估</td></tr><tr><td><strong>幻觉率 (Hallucination Rate)</strong></td><td>模型生成不实信息的比例</td><td>所有生成式 AI</td></tr></tbody></table><h4 id="_6-2-业务指标" tabindex="-1">6.2 业务指标 <a class="header-anchor" href="#_6-2-业务指标" aria-label="Permalink to &quot;6.2 业务指标&quot;">​</a></h4><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td><strong>任务完成率 (Task Success Rate)</strong></td><td>用户能否成功完成目标</td></tr><tr><td><strong>用户满意度 (CSAT / NPS)</strong></td><td>用户对 AI 的满意程度</td></tr><tr><td><strong>时间节省</strong></td><td>相比人工流程节省的时间</td></tr><tr><td><strong>成本节约</strong></td><td>节约的人力/运营成本</td></tr><tr><td><strong>留存率</strong></td><td>用户是否持续使用 AI 功能</td></tr><tr><td><strong>人机回退率</strong></td><td>AI 无法处理时转人工的比例（越低越好）</td></tr></tbody></table><h4 id="_6-3-评估方法" tabindex="-1">6.3 评估方法 <a class="header-anchor" href="#_6-3-评估方法" aria-label="Permalink to &quot;6.3 评估方法&quot;">​</a></h4><ul><li><strong>离线评估</strong>：用标注数据集在开发环境跑指标，快速迭代</li><li><strong>在线评估</strong>：A/B 测试、金丝雀发布、灰度对比</li><li><strong>人工评估</strong>：抽样标注、红队测试（Red Teaming）</li><li><strong>用户反馈</strong>：赞/踩按钮、满意度问卷、用户访谈</li></ul><p><strong>设计原则：</strong></p><ul><li><strong>离线和在线指标缺一不可</strong>：离线好不一定在线好，反之亦然</li><li><strong>不要只看平均分</strong>：关注长尾分布——最差的 10% 用户可能决定了产品的口碑</li><li><strong>建立评估数据集评审机制</strong>：评估集也需要定期更新和检查 bias</li></ul><hr><h3 id="模块-7-成本模型" tabindex="-1">模块 7：成本模型 <a class="header-anchor" href="#模块-7-成本模型" aria-label="Permalink to &quot;模块 7：成本模型&quot;">​</a></h3><p><strong>核心问题：AI 产品到底要花多少钱？ROI 怎么样？</strong></p><table tabindex="0"><thead><tr><th>成本类别</th><th>明细</th><th>月估量级（参考）</th></tr></thead><tbody><tr><td><strong>推理成本</strong></td><td>模型 API 调用费 / GPU 算力 / 带宽</td><td>$100 ~ $100K+</td></tr><tr><td><strong>训练/微调成本</strong></td><td>GPU 时长、数据标注、工程师人力</td><td>$1K ~ $1M+</td></tr><tr><td><strong>数据成本</strong></td><td>采集、标注、清理、存储</td><td>$500 ~ $50K</td></tr><tr><td><strong>基础设施</strong></td><td>服务器、数据库、CDN、监控</td><td>$500 ~ $20K</td></tr><tr><td><strong>人力成本</strong></td><td>PM、AI 工程师、标注团队、运维</td><td>$10K ~ $200K+</td></tr></tbody></table><p><strong>成本优化策略：</strong></p><ol><li><strong>缓存策略</strong>：对相同或相似请求做缓存，减少重复推理</li><li><strong>模型级联</strong>：先用小模型处理简单请求，复杂请求才调用大模型</li><li><strong>批处理</strong>：非实时场景使用批量推理，提高 GPU 利用率</li><li><strong>蒸馏量化</strong>：用大模型蒸馏小模型，降低推理成本 5-10 倍</li><li><strong>Token 优化</strong>：精简 prompt、压缩上下文，减少 Token 消耗</li></ol><hr><h3 id="模块-8-伦理与风险" tabindex="-1">模块 8：伦理与风险 <a class="header-anchor" href="#模块-8-伦理与风险" aria-label="Permalink to &quot;模块 8：伦理与风险&quot;">​</a></h3><p><strong>核心问题：AI 产品可能带来什么负面后果？如何防范？</strong></p><table tabindex="0"><thead><tr><th>风险类别</th><th>具体风险</th><th>缓解措施</th></tr></thead><tbody><tr><td><strong>偏见/歧视</strong></td><td>模型对特定群体输出不公结果</td><td>多样性数据集、偏见检测、公平性评估</td></tr><tr><td><strong>幻觉</strong></td><td>模型生成虚假信息</td><td>RAG 约束、事实核查、置信度显示</td></tr><tr><td><strong>滥用</strong></td><td>被用于生成有害内容、诈骗</td><td>内容过滤、使用限制、用户身份验证</td></tr><tr><td><strong>隐私泄露</strong></td><td>用户数据被泄露或滥用</td><td>数据最小化、脱敏、加密、合规审计</td></tr><tr><td><strong>依赖风险</strong></td><td>用户过度依赖 AI 失去判断力</td><td>透明提示、人工复核机制</td></tr><tr><td><strong>安全</strong></td><td>Prompt 注入、越狱攻击</td><td>输入过滤、权限控制、持续红队测试</td></tr></tbody></table><p><strong>设计原则：</strong></p><ul><li><strong>默认保守</strong>：不确定时保守输出，而非过度自信</li><li><strong>透明可解释</strong>：让用户知道这是 AI 输出，并了解模型的不确定性</li><li><strong>人工兜底</strong>：关键决策场景必须有人的参与（Human-in-the-Loop）</li></ul><hr><h3 id="模块-9-落地路径" tabindex="-1">模块 9：落地路径 <a class="header-anchor" href="#模块-9-落地路径" aria-label="Permalink to &quot;模块 9：落地路径&quot;">​</a></h3><p><strong>核心问题：从想法到上线，具体分几步？</strong></p><h4 id="阶段-1-验证-1-4-周" tabindex="-1">阶段 1：验证（1-4 周） <a class="header-anchor" href="#阶段-1-验证-1-4-周" aria-label="Permalink to &quot;阶段 1：验证（1-4 周）&quot;">​</a></h4><ul><li>用现成 API 快速搭建 demo</li><li>用 50-100 个真实场景测试可行性</li><li>确定核心指标基线</li></ul><h4 id="阶段-2-mvp-4-8-周" tabindex="-1">阶段 2：MVP（4-8 周） <a class="header-anchor" href="#阶段-2-mvp-4-8-周" aria-label="Permalink to &quot;阶段 2：MVP（4-8 周）&quot;">​</a></h4><ul><li>构建最小闭环：输入 → AI 处理 → 输出</li><li>建立基础评估 pipeline</li><li>内部小范围用户测试</li><li>确定模型选型和部署方案</li></ul><h4 id="阶段-3-发布-4-12-周" tabindex="-1">阶段 3：发布（4-12 周） <a class="header-anchor" href="#阶段-3-发布-4-12-周" aria-label="Permalink to &quot;阶段 3：发布（4-12 周）&quot;">​</a></h4><ul><li>集成到产品中，完善前后端交互</li><li>建立监控和告警体系（延迟、错误率、用户反馈）</li><li>灰度发布，逐步放量</li><li>收集用户数据启动数据飞轮</li></ul><h4 id="阶段-4-迭代-持续" tabindex="-1">阶段 4：迭代（持续） <a class="header-anchor" href="#阶段-4-迭代-持续" aria-label="Permalink to &quot;阶段 4：迭代（持续）&quot;">​</a></h4><ul><li>基于用户反馈优化 prompt / RAG / 微调</li><li>A/B 测试新模型和策略</li><li>成本优化</li><li>扩展新场景</li></ul><hr><h2 id="三、完整案例-ai-智能客服机器人" tabindex="-1">三、完整案例：AI 智能客服机器人 <a class="header-anchor" href="#三、完整案例-ai-智能客服机器人" aria-label="Permalink to &quot;三、完整案例：AI 智能客服机器人&quot;">​</a></h2><h3 id="模块填写示例" tabindex="-1">模块填写示例 <a class="header-anchor" href="#模块填写示例" aria-label="Permalink to &quot;模块填写示例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>内容</th></tr></thead><tbody><tr><td><strong>问题定义</strong></td><td>用户咨询量 5000+/天，人工客服只能覆盖 60%，平均等待 3 分钟</td></tr><tr><td><strong>用户价值</strong></td><td>24/7 即时响应，95% 常见问题自助解决</td></tr><tr><td><strong>市场定位</strong></td><td>面向电商平台的中小商家，按对话量定价</td></tr><tr><td><strong>模型选型</strong></td><td>API 使用 DeepSeek V3（主），本地部署 Qwen-7B（备用）</td></tr><tr><td><strong>数据策略</strong></td><td>知识库文档（FAQ、政策、商品目录）+ 历史对话记录（脱敏）</td></tr><tr><td><strong>评估指标</strong></td><td>解决率 ≥ 85%，用户满意度 ≥ 4.2/5，转人工率 &lt; 20%</td></tr><tr><td><strong>成本模型</strong></td><td>API $3000/月，人力 2 名 AI 工程师 + 1 名 PM，总计 ~$25K/月</td></tr><tr><td><strong>伦理风险</strong></td><td>确保不泄露用户隐私，不承诺没有的售后服务，幻觉管控</td></tr><tr><td><strong>落地路径</strong></td><td>W1-2 搭建原型验证，W3-6 MVP 内测，W7-10 灰度发布，持续迭代</td></tr></tbody></table><hr><h2 id="四、ai-产品画布使用建议" tabindex="-1">四、AI 产品画布使用建议 <a class="header-anchor" href="#四、ai-产品画布使用建议" aria-label="Permalink to &quot;四、AI 产品画布使用建议&quot;">​</a></h2><ol><li><strong>团队共创</strong>：在画布前召集 PM、工程师、数据科学家、设计师一起讨论</li><li><strong>迭代更新</strong>：画布不是一次性产出，每个阶段都要重新审视</li><li><strong>重点突出</strong>：不同产品侧重点不同——RAG 产品重点在数据策略，Agent 产品重点在工具定义</li><li><strong>保持简洁</strong>：每个模块写清楚核心要点即可，不必长篇大论</li><li><strong>文档化</strong>：把画布内容记入 PRD，作为后续决策的参考依据</li></ol><hr><h2 id="五、checklist-ai-产品准备度检查" tabindex="-1">五、Checklist：AI 产品准备度检查 <a class="header-anchor" href="#五、checklist-ai-产品准备度检查" aria-label="Permalink to &quot;五、Checklist：AI 产品准备度检查&quot;">​</a></h2><ul><li>[ ] 问题定义清晰，AI 必要性成立</li><li>[ ] 目标用户和使用场景明确</li><li>[ ] 模型选型有明确的权衡分析</li><li>[ ] 数据来源、质量、合规已评估</li><li>[ ] 离线评估指标 &gt; 基线，在线评估方案已设计</li><li>[ ] 成本模型可接受，ROI 为正</li><li>[ ] 伦理风险已被识别并有缓解措施</li><li>[ ] 落地路径有时间线和里程碑</li><li>[ ] 团队具备 AI 产品交付能力</li><li>[ ] 有模型切换和回退方案</li></ul><hr><blockquote><p><strong>参考资源：</strong> Lean Canvas（精益画布）启发下的 AI 产品化改编，结合 Google PAIR Guide、OpenAI Cookbook、Andrej Karpathy 的 AI 产品开发理念以及行业最佳实践。</p></blockquote>`,79)])])}const u=r(d,[["render",o]]);export{c as __pageData,u as default};
